import assert from 'node:assert/strict';
import { createInitialBoardState, type BoardState, type PieceType, type Player } from '../../src/types/shogi';
import { normalizePositionHistory } from '../../src/domain/shogi/repetition';
import { normalizePositionSnapshots } from '../../src/domain/shogi/replay';
import { isPlayerInCheck } from '../../src/domain/shogi/checkmate';
import { executeLegalAction, getLegalActions } from '../../src/domain/shogi/legalActions';

export type Placement = [number, number, PieceType, Player];
export const other = (p: Player): Player => p === 'sente' ? 'gote' : 'sente';
export function constructed(id: string, placements: Placement[], turn: Player = 'sente'): BoardState {
  let state = createInitialBoardState();
  state.recordId = id;
  for (const row of state.squares) for (const square of row) square.piece = null;
  placements.forEach(([r, c, type, player], i) => {
    assert.equal(state.squares[r][c].piece, null);
    state.squares[r][c].piece = { id: `${id}-${i}`, type, player };
  });
  state.turn = turn;
  state.status = isPlayerInCheck(state, turn) ? 'check' : 'active';
  state.positionHistory = []; state.positionSnapshots = [];
  state = normalizePositionSnapshots(normalizePositionHistory(state));
  return state;
}
export function rotate(state: BoardState, id: string): BoardState {
  assert.equal(state.history.length, 0);
  const placements: Placement[] = state.squares.flatMap(row => row.flatMap(s => s.piece
    ? [[8 - s.row, 8 - s.col, s.piece.type, other(s.piece.player)] as Placement] : []));
  return constructed(id, placements, other(state.turn));
}
export interface TacticalPosition {
  id: string;
  origin: string;
  purpose: string;
  state: BoardState;
  referenceWinner: Player;
  referenceDepth: number;
  expectation: 'shortest-win' | 'longest-resistance' | 'avoid-loss' | 'capture';
  // Coordinate predicate is independent of engine evaluation/order.
  target?: { from: [number, number]; to: [number, number]; avoid: boolean };
}
export function tacticalPositions(): TacticalPosition[] {
  // Adapted from shogi-checkmate.test.tsx:createSenteMatingMovePosition.
  const mating: Placement[] = [[8,4,'king','sente'],[0,4,'king','gote'],
    [2,4,'rook','sente'],[1,4,'silver','gote'],[2,3,'gold','sente'],
    [2,1,'bishop','sente'],[2,7,'bishop','sente']];
  const mate = constructed('mate-sente', mating);
  const trap = constructed('recapture', [[8,8,'king','sente'],[0,8,'king','gote'],
    [5,4,'rook','sente'],[4,4,'pawn','gote'],[3,4,'gold','gote']]);
  const undefended = constructed('capture', [[8,8,'king','sente'],[0,8,'king','gote'],
    [5,4,'rook','sente'],[4,4,'pawn','gote']]);
  const defence = constructed('evasion', [[8,4,'king','sente'],[0,8,'king','gote'],[4,4,'rook','gote']]);
  const loss = constructed('resistance', [[0,1,'king','gote'],[2,1,'king','sente'],[2,3,'gold','sente'],[3,0,'gold','sente']], 'gote');
  const three = constructed('mate-three', [[0,0,'king','gote'],[2,1,'king','sente'],[3,0,'gold','sente']]);
  const mixed = constructed('mixed-distance', [[0,0,'king','gote'],[2,1,'king','sente'],[2,0,'gold','sente'],[3,2,'gold','sente']]);
  const base = (id: string, state: BoardState, purpose: string, expectation: TacticalPosition['expectation'], winner: Player = state.turn): TacticalPosition =>
    ({ id, state, purpose, expectation, referenceWinner: winner, referenceDepth: 3,
      origin: 'constructed; omitted pieces outside problem, not in hands; no claim of hirate reachability' });
  // Legal replay from hirate, using public enumeration/application, retaining history.
  let replay = createInitialBoardState(); replay.recordId = 'hirate-exchange';
  for (const [fr,fc,tr,tc] of [[6,0,5,0],[2,0,3,0],[5,0,4,0],[3,0,4,0],[8,0,4,0],[2,1,3,1]]) {
    const action = getLegalActions(replay).find(a => a.kind === 'move' && a.from.row === fr && a.from.col === fc && a.to.row === tr && a.to.col === tc);
    assert.ok(action); const next = executeLegalAction(replay, action); assert.equal(next.type, 'applied');
    if (next.type === 'applied') replay = next.state;
  }
  return [
    { ...base('mate-sente', mate, 'mate one; alternative forced wins and original-order ties', 'shortest-win'), origin: 'adapted existing checkmate fixture; constructed, both kings present' },
    base('mate-gote', rotate(mate, 'mate-gote'), 'rotated mate; root score direction', 'shortest-win'),
    base('mate-three', three, 'three-ply forced mate including every king reply; quiet first move', 'shortest-win'),
    base('mixed-distance', mixed, 'one-ply and three-ply forced wins in same root', 'shortest-win'),
    { ...base('resistance', loss, 'all responses; unavoidable loss with two/four-ply resistance', 'longest-resistance', 'sente'), referenceDepth: 4 },
    base('evasion', defence, 'all legal actions must resolve check; avoid forced loss if proven', 'avoid-loss', 'gote'),
    { ...base('recapture', trap, 'adapted q captureTrap; recapturer gold replaces second same-file pawn to avoid nifu', 'capture'), target: { from: [5,4], to: [4,4], avoid: true } },
    { ...base('capture', undefended, 'unprotected pawn capture control', 'capture'), target: { from: [5,4], to: [4,4], avoid: false } },
    { ...base('recapture-gote', rotate(trap, 'recapture-gote'), 'rotated poisoned pawn and q cap', 'capture'), target: { from: [3,4], to: [4,4], avoid: true } },
    { ...base('hirate-exchange', replay, 'legal opening replay with captured pawn in hand; reference deliberately bounded', 'avoid-loss', 'gote'), origin: 'hirate replay: (6,0)-(5,0), (2,0)-(3,0), (5,0)-(4,0), (3,0)-(4,0), (8,0)-(4,0), (2,1)-(3,1); 0-based row,col' },
  ];
}

scripts/benchmarks/terminalDistanceRefer:
import assert from 'node:assert/strict';
import type { BoardState, Player } from '../../src/types/shogi';
import { getLegalActions, executeLegalAction, type LegalAction } from '../../src/domain/shogi/legalActions';
import { evaluateSearchPositionBreakdown, type SearchEvaluationBreakdown } from '../../src/domain/shogi/twoPlyMinimaxAi';
import { isPlayerInCheck } from '../../src/domain/shogi/checkmate';
import { constructed, rotate, tacticalPositions } from './tacticalPositions';

export function distancePositions() {
  const loss = constructed('terminal-resistance', [[0,1,'king','gote'],[2,0,'king','sente'],
    [1,5,'gold','sente'],[2,1,'gold','sente']], 'gote');
  return [...tacticalPositions(), { id: 'terminal-resistance', state: loss },
    { id: 'terminal-resistance-gote', state: rotate(loss, 'terminal-resistance-gote') }];
}

export function apply(s: BoardState, a: LegalAction) {
  const e = executeLegalAction(s, a); assert.equal(e.type, 'applied');
  if (e.type !== 'applied') throw Error('execution');
  return e.state;
}

export interface ReferenceLeaf {
  breakdown: SearchEvaluationBreakdown;
  pv: LegalAction[];
  terminalDistancePly: number | null;
  reason: string | null;
}

// Independent comparison: no product search value, search recursion, pruning,
// ordering, or q implementation. Draw stays a numeric zero, with no distance.
export function compareReference(a: ReferenceLeaf, b: ReferenceLeaf): number {
  const rank = (v: ReferenceLeaf) => v.breakdown.terminal === 'win' ? 2 : v.breakdown.terminal === 'loss' ? 0 : 1;
  if (rank(a) !== rank(b)) return rank(a) - rank(b);
  if (a.breakdown.terminal === 'win') return b.terminalDistancePly! - a.terminalDistancePly!;
  if (a.breakdown.terminal === 'loss') return a.terminalDistancePly! - b.terminalDistancePly!;
  return a.breakdown.total === b.breakdown.total ? 0 : a.breakdown.total > b.breakdown.total ? 1 : -1;
}

export function exhaustive(s: BoardState, depth: number, q: number | null = null,
  root: Player = s.turn, ply = 0, reverse = false): ReferenceLeaf {
  const breakdown = evaluateSearchPositionBreakdown(s, root);
  const stand: ReferenceLeaf = { breakdown, pv: [],
    terminalDistancePly: breakdown.terminal === 'win' || breakdown.terminal === 'loss' ? ply : null,
    reason: s.result?.endReason ?? null };
  if (s.status === 'ended' || depth === 0 && (q === null || q === 0)) return stand;
  const tactical = depth === 0;
  const checked = tactical && isPlayerInCheck(s, s.turn);
  let actions = getLegalActions(s);
  if (tactical && !checked) actions = actions.filter(a => a.kind === 'move' && s.squares[a.to.row][a.to.col].piece !== null);
  if (reverse) actions.reverse();
  let best: ReferenceLeaf | null = tactical && !checked ? stand : null;
  for (const a of actions) {
    const v = exhaustive(apply(s,a), Math.max(0,depth-1), tactical ? q! - 1 : q, root, ply+1, reverse);
    const candidate = { ...v, pv: [a,...v.pv] };
    if (!best || (s.turn === root ? compareReference(candidate,best)>0 : compareReference(candidate,best)<0)) best = candidate;
  }
  return best ?? stand;
}

export function observePv(s: BoardState, pv: readonly LegalAction[], root = s.turn): ReferenceLeaf {
  let leaf = s;
  for (const a of pv) { assert.ok(getLegalActions(leaf).some(b => JSON.stringify(a) === JSON.stringify(b))); leaf = apply(leaf,a); }
  if (leaf.result?.endReason === 'checkmate' || leaf.result?.endReason === 'no_legal_actions') {
    const active = {...leaf, status: 'active' as const, result: null};
    assert.equal(getLegalActions(active).length,0);
    assert.equal(isPlayerInCheck(active,leaf.turn),leaf.result.endReason==='checkmate');
  }
  const breakdown = evaluateSearchPositionBreakdown(leaf,root);
  return { breakdown, pv: [...pv], terminalDistancePly: breakdown.terminal === 'win' || breakdown.terminal === 'loss' ? pv.length : null,
    reason: leaf.result?.endReason ?? null };
}

scripts/benchmarks/checkEvasionPositions:
import { constructed, rotate, tacticalPositions, type TacticalPosition } from './tacticalPositions';

// Fixed before any A/B/C outcomes. Sparse problems omit unused material;
// only hirate-exchange claims reachability from the initial position.
export function checkEvasionPositions(): TacticalPosition[] {
  const chain = constructed('countercheck', [[8,4,'king','sente'],[4,8,'king','gote'],
    [4,4,'rook','gote'],[4,0,'rook','sente']]);
  const single = constructed('single-evasion', [[8,8,'king','sente'],[6,6,'king','gote'],[6,8,'rook','gote']]);
  const base = (id: string, state: typeof chain): TacticalPosition => ({ id, state,
    origin: 'constructed; missing pieces outside problem; hirate reachability not claimed',
    purpose: 'q boundary check evasions and counterchecks', expectation: 'avoid-loss',
    referenceWinner: state.turn === 'sente' ? 'gote' : 'sente', referenceDepth: 3 });
  return [...tacticalPositions(), base('countercheck', chain),
    base('countercheck-gote', rotate(chain, 'countercheck-gote')),
    base('single-evasion', single), base('single-evasion-gote', rotate(single, 'single-evasion-gote'))];
}

scripts/benchmarks/checkEvasionReference:
import type { BoardState, Player } from '../../src/types/shogi';
import { getLegalActions } from '../../src/domain/shogi/legalActions';
import { isPlayerInCheck } from '../../src/domain/shogi/checkmate';
import { evaluateSearchPositionBreakdown, evaluateNoLegalActionsPositionBreakdown } from '../../src/domain/shogi/twoPlyMinimaxAi';
import { apply, compareReference, type ReferenceLeaf } from './terminalDistanceReference';

// Full-width reference: no product search, searchValue, pruning, ordering or TT.
// Shares legal execution and static evaluator, so this is not an independent rules engine.
export function evasionReference(s: BoardState, depth: number, q: number, extra: number,
  root: Player = s.turn, ply = 0, reverse = false): ReferenceLeaf {
  let breakdown = evaluateSearchPositionBreakdown(s, root);
  const checked = isPlayerInCheck(s, s.turn);
  const tactical = depth === 0;
  const extending = tactical && q === 0 && checked && extra > 0;
  const leaf = (): ReferenceLeaf => ({ breakdown, pv: [], reason: s.result?.endReason ?? null,
    terminalDistancePly: breakdown.terminal === 'win' || breakdown.terminal === 'loss' ? ply : null });
  if (s.status === 'ended' || tactical && q === 0 && !extending) return leaf();
  let actions = getLegalActions(s);
  if (extending && actions.length === 0) { breakdown = evaluateNoLegalActionsPositionBreakdown(s,root); return leaf(); }
  if (tactical && !checked) actions = actions.filter(a => a.kind === 'move' && s.squares[a.to.row][a.to.col].piece !== null);
  if (reverse) actions.reverse();
  let best: ReferenceLeaf | null = tactical && !checked ? leaf() : null;
  for (const a of actions) {
    const v = evasionReference(apply(s,a), Math.max(0,depth-1), tactical ? Math.max(0,q-1) : q,
      extra - (extending ? 1 : 0),root,ply+1,reverse);
    const candidate = { ...v, pv:[a,...v.pv] };
    if (!best || (s.turn === root ? compareReference(candidate,best)>0 : compareReference(candidate,best)<0)) best=candidate;
  }
  return best ?? leaf();
}
